std::optional<Std14Widths> std14_widths(std::string_view name)
{
    if (name == "Helvetica")
        return Std14Widths { face0, nullptr };
    if (name == "Helvetica-Bold")
        return Std14Widths { face1, nullptr };
    if (name == "Helvetica-Oblique")
        return Std14Widths { face2, nullptr };
    if (name == "Helvetica-BoldOblique")
        return Std14Widths { face3, nullptr };
    if (name == "Times-Roman")
        return Std14Widths { face4, nullptr };
    if (name == "Times-Bold")
        return Std14Widths { face5, nullptr };
    if (name == "Times-Italic")
        return Std14Widths { face6, nullptr };
    if (name == "Times-BoldItalic")
        return Std14Widths { face7, nullptr };
    if (name == "Courier")
        return Std14Widths { face8, nullptr };
    if (name == "Courier-Bold")
        return Std14Widths { face9, nullptr };
    if (name == "Courier-Oblique")
        return Std14Widths { face10, nullptr };
    if (name == "Courier-BoldOblique")
        return Std14Widths { face11, nullptr };
    if (name == "Symbol")
        return Std14Widths { {}, codes12 };
    if (name == "ZapfDingbats")
        return Std14Widths { {}, codes13 };
    return std::nullopt;
}

